/*
 * "Things I Do" action animations. Unlike the songs, an action has no soundtrack to
 * sync against — the renderer (components/ActionAnimation.jsx) just loops these key
 * frames on a fixed interval, so a verb literally MOVES instead of sitting still.
 * Keyed by the item's `sound` key (content.js `doing[]`, e.g. do-riding). Each frame is
 * an anchor-conditioned WebP in public/images (generated by scripts/gen-action-poses.mjs),
 * so the same child appears in every frame; a few social verbs show BOTH children.
 *
 *   frames — 2–3 pose keys, hard-cut (flip-book) in order and looped. A hard cut, not a
 *            fade: an action's frames can differ a lot in silhouette and fading ghosts them.
 *   ms     — hold per frame (smaller = quicker motion)
 */
export const ACTION_ANIMATIONS = {
  // BOY solo — a gentle 2-frame pedal (foot up ↔ down). We tried a 4-frame full-circle
  // loop, but independently-generated frames don't register pixel-for-pixel, so fast
  // cutting made the whole child jitter. Two frames at a calm pace read as smooth pedalling.
  'do-riding': { frames: ['act-bike-down', 'act-bike-up'], ms: 380 },
  // GIRL solo — blow, then bubbles float up (gentler).
  'do-blowing': { frames: ['act-bubbles-blow', 'act-bubbles-float'], ms: 780 },
  // BOTH children — reach, then a warm hug.
  'do-hugging': { frames: ['act-hug-open', 'act-hug-squeeze'], ms: 720 },

  // ---- GIRL solo ----
  'do-washing': { frames: ['act-wash-1', 'act-wash-2'], ms: 620 },
  'do-drinking': { frames: ['act-drink-1', 'act-drink-2'], ms: 700 },
  'do-walking': { frames: ['act-walk-1', 'act-walk-2'], ms: 420 }, // quicker = stepping
  'do-jumping': { frames: ['act-jump-1', 'act-jump-2'], ms: 480 },
  'do-brushing': { frames: ['act-brush-1', 'act-brush-2'], ms: 520 },
  'do-kicking': { frames: ['act-kick-1', 'act-kick-2'], ms: 520 },
  'do-waving': { frames: ['act-wave-1', 'act-wave-2'], ms: 460 },

  // ---- BOY solo ----
  'do-eating': { frames: ['act-eat-1', 'act-eat-2'], ms: 660 },
  'do-sleeping': { frames: ['act-sleep-1', 'act-sleep-2'], ms: 1100 }, // slow, calm breathing
  'do-running': { frames: ['act-run-1', 'act-run-2'], ms: 360 }, // quick = fast run
  'do-clapping': { frames: ['act-clap-1', 'act-clap-2'], ms: 420 },
  'do-climbing': { frames: ['act-climb-1', 'act-climb-2'], ms: 560 },
  'do-reading': { frames: ['act-read-1', 'act-read-2'], ms: 900 }, // gentle page turn
  'do-swimming': { frames: ['act-swim-1', 'act-swim-2'], ms: 520 },

  // ---- BOTH children (social) ----
  'do-dancing': { frames: ['act-dance-1', 'act-dance-2'], ms: 560 },
  'do-laughing': { frames: ['act-laugh-1', 'act-laugh-2'], ms: 620 },
  'do-playing': { frames: ['act-play-1', 'act-play-2'], ms: 780 },

  // ---- Round 2 additions ----
  'do-crying': { frames: ['act-cry-1', 'act-cry-2'], ms: 640 }, // girl (emotion)
  'do-painting': { frames: ['act-paint-1', 'act-paint-2'], ms: 700 }, // girl (creative)
  'do-throwing': { frames: ['act-throw-1', 'act-throw-2'], ms: 480 }, // boy (motor)
  'do-cooking': { frames: ['act-cook-1', 'act-cook-2'], ms: 700 }, // boy (routine)
  'do-peekaboo': { frames: ['act-peek-1', 'act-peek-2'], ms: 700 }, // both (social game)
}
